CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.organizations TO authenticated;
GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_org ON public.organizations FOR ALL TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE TABLE public.assessments (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE, answers jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.assessments TO authenticated;
GRANT ALL ON public.assessments TO service_role;
ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_assessment ON public.assessments FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE TABLE public.ai_systems (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE, systems jsonb NOT NULL DEFAULT '[]'::jsonb);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_systems TO authenticated;
GRANT ALL ON public.ai_systems TO service_role;
ALTER TABLE public.ai_systems ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_systems ON public.ai_systems FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE TABLE public.guardrail_configs (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE, tier text NOT NULL DEFAULT 'High', controls jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.guardrail_configs TO authenticated;
GRANT ALL ON public.guardrail_configs TO service_role;
ALTER TABLE public.guardrail_configs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_guardrails ON public.guardrail_configs FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE TABLE public.roadmap_items (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE, items jsonb NOT NULL DEFAULT '[]'::jsonb);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.roadmap_items TO authenticated;
GRANT ALL ON public.roadmap_items TO service_role;
ALTER TABLE public.roadmap_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roadmap ON public.roadmap_items FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE TABLE public.sources (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE, entries jsonb NOT NULL DEFAULT '[]'::jsonb);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sources TO authenticated;
GRANT ALL ON public.sources TO service_role;
ALTER TABLE public.sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_sources ON public.sources FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE FUNCTION public.save_aegis_workspace(p_org uuid, p_name text, p_state jsonb, p_sources jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE result uuid;
BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
IF p_org IS NULL THEN INSERT INTO public.organizations(name) VALUES(p_name) RETURNING id INTO result; ELSE SELECT id INTO result FROM public.organizations WHERE id=p_org AND owner_id=auth.uid(); IF result IS NULL THEN RAISE EXCEPTION 'Workspace unavailable'; END IF; END IF;
INSERT INTO public.assessments(organization_id,answers) VALUES(result,p_state->'answers') ON CONFLICT(organization_id) DO UPDATE SET answers=excluded.answers,updated_at=now();
INSERT INTO public.ai_systems(organization_id,systems) VALUES(result,p_state->'systems') ON CONFLICT(organization_id) DO UPDATE SET systems=excluded.systems;
INSERT INTO public.guardrail_configs(organization_id,tier,controls) VALUES(result,p_state->>'tier',p_state->'gr') ON CONFLICT(organization_id) DO UPDATE SET tier=excluded.tier,controls=excluded.controls;
INSERT INTO public.roadmap_items(organization_id,items) VALUES(result,p_state->'roadmap') ON CONFLICT(organization_id) DO UPDATE SET items=excluded.items;
INSERT INTO public.sources(organization_id,entries) VALUES(result,p_sources) ON CONFLICT(organization_id) DO UPDATE SET entries=excluded.entries;
RETURN result;
END; $$;
REVOKE ALL ON FUNCTION public.save_aegis_workspace(uuid,text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_aegis_workspace(uuid,text,jsonb,jsonb) TO authenticated;